RAW_STDERR_RE = re.compile(r">\s*&2")
DIAGNOSTIC_CMD_RE = re.compile(r"(?:^|[;&|({])\s*(echo|printf|cat)(?:\s|$)")
HEREDOC_RE = re.compile(r"<<-?\s*(['\"]?)([A-Za-z_][A-Za-z0-9_]*)\1")

